package com.cretas.aims.blueprint.draftentry;
import com.cretas.aims.entity.deviationcapadraft.DeviationCapaTemplateDraft; import com.cretas.aims.entity.qualityreleasedraft.QualityReleaseTemplateDraft; import com.cretas.aims.entity.bomdraft.BomRecipeDraft; import com.cretas.aims.entity.warehousecontrol.WarehouseControlDraft; import com.cretas.aims.repository.deviationcapadraft.DeviationCapaTemplateDraftRepository; import com.cretas.aims.repository.qualityreleasedraft.QualityReleaseTemplateDraftRepository; import com.cretas.aims.repository.bomdraft.BomRecipeDraftRepository; import com.cretas.aims.repository.warehousecontrol.WarehouseControlDraftRepository; import com.cretas.aims.service.tracerecalldraft.TraceRecallPlanDraftCommand; import com.cretas.aims.service.tracerecalldraft.TraceRecallPlanDraftModels.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Component; import java.util.*;
@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name = "cretas.platform.factory-assembly.enabled", havingValue = "true", matchIfMissing = false)
@Component public class TraceRecallDraftProposer implements CapabilityDraftProposer { private static final String WHY="蓝图没有追溯方向、遍历边界、完成时限、质量证据和升级责任的完整事实"; private static List<RequiredInput> policyFields(){return List.of(RequiredInput.oneOf("direction","追溯方向",WHY,ec(TraceDirection.class),opts(TraceDirection.class)),RequiredInput.integer("maxTraversalDepth","最大深度",WHY,"1–100",1,100),RequiredInput.integer("maxTraversalNodes","最大节点",WHY,"1–100000",1,100000),RequiredInput.integer("traceCompletionMinutes","完成分钟",WHY,"1–10080",1,10080),RequiredInput.integer("massBalanceToleranceBasisPoints","平衡容差",WHY,"0–10000",0,10000),RequiredInput.integer("mockRecallFrequencyDays","演练周期",WHY,"1–3650",1,3650),RequiredInput.integer("evidenceRetentionDays","证据保留",WHY,"1–3650",1,3650),RequiredInput.values("escalationRoles","升级责任",WHY,"至少 1 项","责任",1,4,RequiredInput.oneOf("role","责任",WHY,ec(EscalationRole.class),opts(EscalationRole.class))),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500));} private static <E extends Enum<E>> List<Option> opts(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(e->new Option(e.name(),e.name())).toList();} private static <E extends Enum<E>> String ec(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(Enum::name).collect(java.util.stream.Collectors.joining("、"))+" 之一";} private final DeviationCapaTemplateDraftRepository deviation;private final QualityReleaseTemplateDraftRepository quality;private final BomRecipeDraftRepository bom;private final WarehouseControlDraftRepository warehouse; public TraceRecallDraftProposer(DeviationCapaTemplateDraftRepository d,QualityReleaseTemplateDraftRepository q,BomRecipeDraftRepository b,WarehouseControlDraftRepository w){deviation=d;quality=q;bom=b;warehouse=w;} public String capabilityId(){return TraceRecallPlanDraftCommand.CAPABILITY_ID;} private boolean ok(Object row,String f,String bp,long v,String src){if(row instanceof DeviationCapaTemplateDraft x)return f.equals(x.getFactoryId())&&bp.equals(x.getBlueprintId())&&v==x.getBlueprintVersion()&&src.equals(x.getSourceDigest())&&x.getDesiredDigest()!=null&&x.getDesiredDigest().matches("[0-9a-f]{64}")&&"DRAFT".equals(x.getStatus());if(row instanceof QualityReleaseTemplateDraft x)return f.equals(x.getFactoryId())&&bp.equals(x.getBlueprintId())&&v==x.getBlueprintVersion()&&src.equals(x.getSourceDigest())&&x.getDesiredDigest()!=null&&x.getDesiredDigest().matches("[0-9a-f]{64}")&&"DRAFT".equals(x.getStatus());if(row instanceof BomRecipeDraft x)return f.equals(x.getFactoryId())&&bp.equals(x.getBlueprintId())&&v==x.getBlueprintVersion()&&src.equals(x.getSourceDigest())&&x.getDesiredDigest()!=null&&x.getDesiredDigest().matches("[0-9a-f]{64}")&&"DRAFT".equals(x.getStatus());if(row instanceof WarehouseControlDraft x)return f.equals(x.getFactoryId())&&bp.equals(x.getBlueprintId())&&v==x.getBlueprintVersion()&&src.equals(x.getSourceDigest())&&x.getDesiredDigest()!=null&&x.getDesiredDigest().matches("[0-9a-f]{64}")&&"DRAFT".equals(x.getStatus());return false;} public Proposed propose(Source s){long v=s.blueprint().getVersion();var d=deviation.findAll(Example.of(new DeviationCapaTemplateDraft()),Sort.by(Sort.Direction.DESC,"createdAt")).stream().filter(x->ok(x,s.factoryId(),s.blueprint().getId(),v,s.sourceDigest())).findFirst().orElse(null);var q=quality.findAll(Example.of(new QualityReleaseTemplateDraft()),Sort.by(Sort.Direction.DESC,"createdAt")).stream().filter(x->ok(x,s.factoryId(),s.blueprint().getId(),v,s.sourceDigest())).findFirst().orElse(null);var b=bom.findAll(Example.of(new BomRecipeDraft()),Sort.by(Sort.Direction.DESC,"createdAt")).stream().filter(x->ok(x,s.factoryId(),s.blueprint().getId(),v,s.sourceDigest())).findFirst().orElse(null);var w=warehouse.findAll(Example.of(new WarehouseControlDraft()),Sort.by(Sort.Direction.DESC,"createdAt")).stream().filter(x->ok(x,s.factoryId(),s.blueprint().getId(),v,s.sourceDigest())).findFirst().orElse(null);if(d==null||q==null||b==null||w==null)return Proposed.blocked("UPSTREAM_MISSING","追溯召回必须绑定同蓝图偏差、质量、BOM 和仓储草稿","先完成四个上游草稿");var req=new DraftRequest(s.factoryId(),s.blueprint().getId(),v,s.sourceDigest(),new DraftPin(d.getId(),d.getDesiredDigest()),new DraftPin(q.getId(),q.getDesiredDigest()),new DraftPin(b.getId(),b.getDesiredDigest()),new DraftPin(w.getId(),w.getDesiredDigest()),null,null,null,0);return Proposed.single(capabilityId(),"追溯召回计划",req,List.of(RequiredInput.object("policy","追溯策略",WHY,"完整填写",policyFields())),List.of());}}
